(()=>{
const q=s=>document.querySelector(s),R=MeleeRules,ns='http://www.w3.org/2000/svg',ctx=q('#actors').getContext('2d');
let start={r:6,c:3},hero={...start},target={r:1,c:3},blockers=[],mode='direct',editing='hero',state='idle',paused=false,path=null,edge=0,t=0,attack=0,hits=0,hp=120,hitAge=99,last=0,ready=false,reg;
const frames=Array.from({length:12},()=>new Image()),golem=new Image(),party=new Image();
const load=(im,src)=>new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=src});
Promise.all([...frames.map((im,i)=>load(im,'assets/swordsman/frames/frame-'+String(i).padStart(2,'0')+'.png')),load(golem,'assets/flame-sequence.png'),load(party,'assets/formation-party.png'),fetch('assets/swordsman/registration.json').then(r=>r.json()).then(r=>reg=r)]).then(()=>{ready=true;q('#play').disabled=false;reset()}).catch(()=>q('#status').textContent='素材載入失敗，請重新整理。');
function point(p){const x=p.c*65+(p.r%2)*32.5,y=p.r*56;return{x:400-(y-196)*1.28,y:330+(x-211.25)*.86}}
function node(tag,attrs){const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n}
function occupied(){return blockers.some(p=>R.key(p)===R.key(hero))||blockers.some(p=>R.key(p)===R.key(target))}
function plan(){path=R.route(hero,target,blockers);q('#route-info').textContent=path?'預計移動 '+(path.length-1)+' 格，抵達後原地普攻。':'沒有可抵達的相鄰空格。';}
function board(){const svg=q('#ground');svg.innerHTML='<defs><radialGradient id="forest"><stop stop-color="#60795a"/><stop offset="1" stop-color="#273f38"/></radialGradient></defs><rect width="800" height="650" fill="url(#forest)"/>';q('#cells').replaceChildren();
for(let r=0;r<8;r++)for(let c=0;c<7;c++){const p={r,c},center=point(p),vertices=Array.from({length:6},(_,k)=>{const a=(k*60-90)*Math.PI/180,x=c*65+(r%2)*32.5+37*Math.cos(a),y=r*56+37*Math.sin(a);return{x:400-(y-196)*1.28,y:330+(x-211.25)*.86}}),isBlock=blockers.some(b=>R.key(b)===R.key(p));svg.append(node('polygon',{points:vertices.map(v=>v.x+','+v.y).join(' '),fill:isBlock?'#657f85':r>=4?'#99aa83':'#b7b18a',stroke:'#6d7e61','stroke-width':1}));const xs=vertices.map(v=>v.x),ys=vertices.map(v=>v.y),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y,b=document.createElement('button');b.style.cssText=`left:${x/8}%;top:${y/6.5}%;width:${w/8}%;height:${h/6.5}%;clip-path:polygon(${vertices.map(v=>(v.x-x)/w*100+'% '+(v.y-y)/h*100+'%').join(',')})`;b.setAttribute('aria-label',`第${r+1}列第${c+1}欄${isBlock?'，盾衛':''}`);b.onclick=()=>place(p);q('#cells').append(b)}
if(path&&q('#path').checked){svg.append(node('polyline',{points:path.map(point).map(p=>p.x+','+p.y).join(' '),fill:'none',stroke:'#d6eee3','stroke-width':3,'stroke-dasharray':'6 6',opacity:.7}));path.forEach(p=>{const v=point(p);svg.append(node('circle',{cx:v.x,cy:v.y,r:4,fill:'#d5f6ee'}))})}}
function say(s){q('#status').textContent=s}
function reset(){hero={...start};state='idle';paused=false;edge=t=attack=hits=0;hp=120;hitAge=99;plan();board();say('選擇情境後點「開始接敵」。');update()}
function place(p){if(state!=='idle'){say('請先重試，再調整站位。');return}if(blockers.some(b=>R.key(b)===R.key(p))||R.key(p)===R.key(editing==='hero'?target:hero)){say('此格已有單位。');return}if(editing==='hero'&&p.r<4||editing==='target'&&p.r>=4){say('劍士部署在左半場，魔像部署在右半場。');return}if(editing==='hero')start={...p};else target={...p};reset()}
function begin(){plan();if(!path){state='blocked';say('沒有路徑：魔像相鄰格已被占用，停止攻擊。');update();return}state=path.length>1?'moving':'attacking';say(state==='moving'?'接敵中：逐格移動，繞過已占用的格子。':'已進入近戰範圍，準備揮劍。');update()}
function update(){q('#phase').textContent=paused?'已暫停':({idle:'準備',moving:'移動接敵',attacking:'普攻中',victory:'測試完成',blocked:'無路徑'})[state];q('#count').textContent=`命中 ${hits} / 3`;q('#distance').textContent=`距離 ${R.distance(hero,target)} 格`;q('#play').textContent=state==='idle'?'開始接敵':state==='victory'||state==='blocked'?'重新測試':paused?'繼續':'暫停';}
q('#play').onclick=()=>{if(['victory','blocked'].includes(state)){reset();begin()}else if(state==='idle')begin();else paused=!paused;update()};q('#reset').onclick=reset;q('#path').onchange=board;
for(const who of ['hero','target'])q('#edit-'+who).onclick=()=>{editing=who;for(const w of ['hero','target'])q('#edit-'+w).setAttribute('aria-pressed',String(w===who))};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;start={r:6,c:3};target={r:1,c:3};blockers=mode==='blocked'?R.neighbors(target):mode==='detour'?[{r:4,c:3},{r:4,c:4},{r:3,c:3}]:[];document.querySelectorAll('[data-mode]').forEach(v=>v.classList.toggle('active',v===b));reset()});
function shadow(p){ctx.fillStyle='#1b352f66';ctx.beginPath();ctx.ellipse(p.x,p.y+2,25,9,0,0,7);ctx.fill()}
function draw(){if(!ready)return;ctx.setTransform(1.5,0,0,1.5,0,0);ctx.clearRect(0,0,800,650);let p=point(hero),b=point(target);if(state==='moving'&&path[edge+1]){const v=point(path[edge+1]),f=Math.min(1,t/.4);p={x:p.x+(v.x-p.x)*f,y:p.y+(v.y-p.y)*f}}let face=b.x<p.x?-1:1,frame=state==='moving'?Math.floor(t/.1)%4:state==='attacking'?Math.min(11,4+Math.floor(attack/1.25*8)):4;const actors=[...blockers.map(v=>({p:point(v),type:'block'})),{p:b,type:'target'},{p,type:'hero'}].sort((a,b)=>a.p.y-b.p.y);
for(const a of actors){shadow(a.p);ctx.save();ctx.translate(a.p.x,a.p.y);if(a.type==='hero'){const m=reg.items[frame],lunge=state==='attacking'?Math.sin(Math.min(attack/1.25,1)*Math.PI)*9:0;ctx.translate(face*lunge,0);ctx.scale(face*.29,.29);ctx.drawImage(frames[frame],-m.rootX,-m.feet)}else if(a.type==='target'){const recoil=hitAge<.3?Math.sin(hitAge/.3*Math.PI)*7:0;ctx.translate(face*recoil,0);ctx.rotate(recoil*.012);ctx.globalAlpha=hp===0?.4:1;ctx.drawImage(golem,245,0,198,golem.naturalHeight/4,-47,-106,94,106)}else{ctx.drawImage(party,0,0,party.width*.365,party.height,-34,-96,68,96)}ctx.restore()}
ctx.fillStyle='#273e36';ctx.fillRect(b.x-31,b.y-121,62,7);ctx.fillStyle='#e5a066';ctx.fillRect(b.x-30,b.y-120,60*hp/120,5);ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#fff1d1';ctx.fillText(`${hp} / 120`,b.x,b.y-130);
if(state==='attacking'&&attack>.36&&attack<.68){const f=(attack-.36)/.32,x=p.x+(b.x-p.x)*.55,y=p.y-49+(b.y-p.y)*.55;ctx.save();ctx.translate(x,y);ctx.scale(face,1);ctx.globalAlpha=Math.sin(f*Math.PI);ctx.strokeStyle='#ffbd53';ctx.lineWidth=13;ctx.beginPath();ctx.ellipse(0,0,45,29,-.5,-1.9+f*.7,1.3+f*.7);ctx.stroke();ctx.strokeStyle='#fff7d2';ctx.lineWidth=5;ctx.stroke();ctx.restore()}
if(hitAge<.55){ctx.save();ctx.globalAlpha=1-hitAge/.55;ctx.fillStyle='#fff3a4';for(let i=0;i<10;i++){const a=i*2.4,d=8+hitAge*(45+i*4);ctx.fillRect(b.x+Math.cos(a)*d,b.y-55+Math.sin(a)*d,3,3)}ctx.font='bold 19px system-ui';ctx.fillText('-40',b.x,b.y-98-hitAge*35);ctx.restore()}
ctx.font='11px system-ui';ctx.fillStyle='#edf0d2';ctx.fillText('劍士',p.x,p.y+18);ctx.fillText('訓練魔像',b.x,b.y+18);
}
function tick(now){const dt=Math.min(.05,(now-last)/1000||0)*(+q('#speed').value);last=now;if(ready&&!paused){hitAge+=dt;if(state==='moving'){t+=dt;if(t>=.4){t-=.4;hero={...path[++edge]};if(edge===path.length-1){state='attacking';attack=0;say('抵達相鄰格：蓄力 → 斬擊 → 收招。')}update()}}else if(state==='attacking'){const prev=attack;attack+=dt;if(prev<.5&&attack>=.5){if(R.distance(hero,target)!==1){state='blocked';say('目標不在近戰範圍，停止攻擊。')}else{hits++;hp=Math.max(0,hp-40);hitAge=0;update();say(`斬擊命中 ${hits} 次，魔像剩餘生命 ${hp}。`)}}if(attack>=1.25){if(hp===0){state='victory';say('測試完成：接敵後連續三次普攻，擊破魔像。')}attack=0;update()}}}draw();requestAnimationFrame(tick)}plan();board();requestAnimationFrame(tick);
})();
